export function LfaIcon({ name, color, size = 18 }: LfaIconProps) {
  const outlined = OUTLINED_TRACED_ICON[name as keyof typeof OUTLINED_TRACED_ICON];
  if (outlined) {
    return (
      <Svg
        width={size}
        height={size}
        viewBox={outlined.viewBox}
        fill="none"
        stroke={color}
        strokeWidth={9}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <Path d={outlined.d} />
      </Svg>
    );
  }

  const traced = TRACED_ICON[name as keyof typeof TRACED_ICON];
  if (traced) {
    return (
      <Svg width={size} height={size} viewBox={traced.viewBox} fill={color}>
        <Path d={traced.d} fill={color} fillRule="evenodd" />
      </Svg>
    );
  }

  if (name === 'foam-roller') {
    return (
      <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
        <G fill={color} rotation={-35} origin="12, 12">
          <Path
            fillRule="evenodd"
            d="M7 16.25C9.34721 16.25 11.25 14.3472 11.25 12C11.25 9.65279 9.34721 7.75 7 7.75C4.65279 7.75 2.75 9.65279 2.75 12C2.75 14.3472 4.65279 16.25 7 16.25ZM7 14.05C8.13218 14.05 9.05 13.1322 9.05 12C9.05 10.8678 8.13218 9.95 7 9.95C5.86782 9.95 4.95 10.8678 4.95 12C4.95 13.1322 5.86782 14.05 7 14.05Z"
          />
          <Rect x={8.3} y={8.15} width={10.2} height={2.05} rx={1.025} />
          <Rect x={8} y={10.975} width={11.1} height={2.05} rx={1.025} />
          <Rect x={8.3} y={13.8} width={10.2} height={2.05} rx={1.025} />
        </G>
      </Svg>
    );
  }

  if (name === 'pull-up-bar') {
    return (
      <Svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={2.2}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <Path d="M4 20V5h16v15" />
        <Path d="M2 20h4" />
        <Path d="M18 20h4" />
        <Path d="M4 10l5-5" />
        <Path d="M20 10l-5-5" />
      </Svg>
    );
  }

  if (name === 'lower-body') {
    return (
      <Svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <Path d="M8 3.5h8l-1 7.5 2.5 9.5H14L12 13l-2 7.5H6.5L9 11z" />
      </Svg>
    );
  }

  if (name === 'spine') {
    return (
      <Svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <Path d="M12 2.5c-2 2-2 4 0 5s2 3 0 4-2 3 0 4 2 3 0 6" />
        <Path d="M9 5h6M9 9h6M9 13h6M9 17h6M9.5 21h5" />
      </Svg>
    );
  }

  const libraryName = MCI_ICON[name];
  if (!libraryName) return null;
  return <MaterialCommunityIcons name={libraryName} size={size} color={color} />;
}
